<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3">Centro de pendientes</h1><p class="text-muted mb-0">Seguimientos, visitas y solicitudes por atender. Hora de Lima.</p></div><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/crm">Ir al CRM</a></div>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="row g-3 mb-4"><?php $cards=[['overdue','Seguimientos vencidos','?filter=vencidas','danger'],['today','Por atender hoy','?filter=hoy','warning'],['upcoming','Después de hoy','?filter=proximas','primary'],['visitsOverdue','Visitas por regularizar','#visitas-vencidas','danger'],['visitsSoon','Visitas · próximos 7 días','#visitas-proximas','primary'],['reservations','Reservas pendientes','#reservas','primary']]; if ($user['rol']!=='vendedor') $cards[]=['unassigned','Consultas sin asignar','#sin-asignar','warning']; foreach ($cards as [$key,$label,$target,$color]): ?><div class="col-6 col-lg-3"><a class="card card-body h-100 text-decoration-none text-dark border-<?= e($color) ?>" href="<?= BASE_URL ?>/tasks<?= e($target) ?>"><span class="small text-muted"><?= e($label) ?></span><strong class="display-6"><?= (int)$summary[$key] ?></strong></a></div><?php endforeach; ?></div>
<section class="card card-body mb-4"><h2 class="h5">Seguimientos con próxima acción</h2><p class="small text-muted">Se crean desde CRM → Gestionar consulta → Agregar seguimiento y Próxima acción. Los pendientes de consultas cerradas o perdidas no se muestran; su historial se conserva.</p><form method="get" action="<?= BASE_URL ?>/tasks" class="d-flex gap-2 mb-4"><label class="visually-hidden" for="filter">Filtrar pendientes</label><select class="form-select" id="filter" name="filter"><?php foreach (Task::FILTERS as $key=>$label): ?><option value="<?= e($key) ?>" <?= $filter===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary">Filtrar</button></form>
<?php if (!$tasks): ?><p class="text-muted mb-0">No hay seguimientos para este filtro.</p><?php endif; ?>
<?php foreach ($tasks as $task): $done=(bool)$task['tarea_completada_at']; $urgency=Task::urgency($task['proxima_accion'],$clock); ?><article class="border-top py-3"><div class="d-flex flex-wrap justify-content-between gap-2"><h3 class="h6"><?= e($task['cliente']) ?> · <?= e(Lead::TYPES[$task['tipo']]) ?></h3><span class="badge <?= $done ? 'text-bg-success' : ($urgency==='Vencido' ? 'text-bg-danger' : ($urgency==='Hoy' ? 'text-bg-warning' : 'text-bg-info')) ?> align-self-start"><?= $done ? 'Completado' : e($urgency) ?></span></div><p class="small text-muted">Acción programada: <?= e($task['proxima_accion']) ?> (Lima)<br>Vendedor: <?= e($task['vendedor'] ?? 'Sin asignar') ?> · Inmueble: <?= e($task['titulo'] ?? 'Consulta general') ?></p><p style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e($task['detalle']) ?></p><?php if ($done): ?><p class="small text-muted">Atendido por <?= e($task['completada_por'] ?? 'Usuario') ?> · <?= e($task['tarea_completada_at']) ?> (Lima)</p><?php endif; ?><div class="d-flex flex-wrap gap-2 align-items-center"><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/crm/lead?id=<?= (int)$task['lead_id'] ?>">Abrir consulta</a><?php if (!$done || !in_array($task['etapa'],['cerrado','perdido'],true)): ?><form method="post" action="<?= BASE_URL ?>/tasks/resolve?id=<?= (int)$task['id'] ?>"><?= Csrf::field() ?><input type="hidden" name="done" value="<?= $done ? '0' : '1' ?>"><button class="btn btn-sm <?= $done ? 'btn-outline-secondary' : 'btn-success' ?>"><?= $done ? 'Reabrir pendiente' : 'Marcar completado' ?></button></form><?php endif; ?></div></article><?php endforeach; ?><p class="small text-muted mt-3 mb-0">Hasta 100 seguimientos. Los pendientes se ordenan por fecha de acción; los completados, por fecha de atención.</p></section>
<?php foreach (['visitas-vencidas'=>['Visitas por regularizar',$visitsOverdue], 'visitas-proximas'=>['Visitas de los próximos 7 días',$visitsSoon]] as $anchor=>[$heading,$items]): ?><section class="card card-body mb-4" id="<?= e($anchor) ?>"><h2 class="h5"><?= e($heading) ?></h2><p class="small text-muted">Visitas solicitadas o confirmadas. Actualiza su estado y resultado desde Gestionar.</p><?php if (!$items): ?><p class="text-muted mb-0">No hay visitas en esta categoría.</p><?php endif; ?><?php foreach ($items as $item): ?><div class="border-top py-3 d-flex flex-wrap justify-content-between gap-3"><div><strong><?= e($item['cliente']) ?></strong> · <?= e($item['fecha_hora']) ?><div class="small text-muted"><?= e($item['titulo']) ?> · <?= e(Visit::MODES[$item['modalidad']]) ?> · <?= e($item['vendedor'] ?? 'Sin asignar') ?></div></div><a class="btn btn-sm btn-outline-primary align-self-start" href="<?= BASE_URL ?>/visits/edit?id=<?= (int)$item['id'] ?>">Gestionar</a></div><?php endforeach; ?><p class="small text-muted mt-2 mb-0">Hasta 20 visitas, las de fecha más antigua primero.</p></section><?php endforeach; ?>
<section class="card card-body mb-4" id="reservas"><h2 class="h5">Reservas pendientes</h2><p class="small text-muted"><?= $user['rol']==='vendedor' ? 'Estas solicitudes están a tu nombre y esperan una decisión administrativa.' : 'Revisa estas solicitudes para aprobarlas, rechazarlas o cancelarlas.' ?></p><?php if (!$reservations): ?><p class="text-muted mb-0">No hay reservas pendientes.</p><?php endif; ?><?php foreach ($reservations as $item): ?><div class="d-flex flex-wrap justify-content-between gap-3 border-top py-3"><div><strong><?= e($item['cliente']) ?></strong><div class="small text-muted"><?= e($item['titulo']) ?> · <?= e($item['created_at']) ?></div></div><a class="btn btn-sm btn-outline-primary align-self-start" href="<?= BASE_URL ?>/reservations/show?id=<?= (int)$item['id'] ?>">Gestionar</a></div><?php endforeach; ?><p class="small text-muted mt-2 mb-0">Hasta 20 reservas, las de registro más antiguo primero.</p></section>
<?php if ($user['rol']!=='vendedor'): ?><section class="card card-body mb-4" id="sin-asignar"><h2 class="h5">Consultas sin vendedor asignado</h2><?php if (!$unassigned): ?><p class="text-muted mb-0">Todas las consultas abiertas tienen vendedor.</p><?php endif; ?><?php foreach ($unassigned as $item): ?><div class="d-flex flex-wrap justify-content-between gap-3 border-top py-3"><div><strong><?= e($item['cliente']) ?></strong><div class="small text-muted"><?= e($item['created_at']) ?></div></div><a class="btn btn-sm btn-outline-primary align-self-start" href="<?= BASE_URL ?>/crm/lead?id=<?= (int)$item['id'] ?>">Asignar vendedor</a></div><?php endforeach; ?><p class="small text-muted mt-2 mb-0">Hasta 20 consultas, las de registro más antiguo primero.</p></section><?php endif; ?>
<p class="small text-muted">Los recordatorios se calculan al abrir o recargar esta página. No envían correos, WhatsApp ni avisos con el navegador cerrado.</p>
